contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        address to,
        uint256 amount,
        uint256 supply
    ) public {
        address self = address(this);
        require(to != address(0), "to must be non-zero");
        require(to != self, "to must differ from test contract");
        require(amount > 0, "amount must be positive");
        require(supply >= amount, "supply must cover amount");

        uint256 tid = 0;

        c.createGameItem("item", "uri", true, true, supply, 0, 1); if (__ESBMC_reverted()) return;
        c.mint(tid, amount); if (__ESBMC_reverted()) return;

        uint256 fromBefore = c.balanceOf(self, tid); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to, tid); if (__ESBMC_reverted()) return;

        c.safeTransferFrom(self, to, tid, amount, ""); if (__ESBMC_reverted()) return;

        uint256 fromAfter = c.balanceOf(self, tid); if (__ESBMC_reverted()) return;
        uint256 toAfter = c.balanceOf(to, tid); if (__ESBMC_reverted()) return;

        assert(fromAfter == fromBefore - amount && toAfter == toBefore + amount);
    }

    receive() external payable {}
}

