    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address to, uint256 amount, uint256 supply) internal {
        address self = address(this);
        vm.assume(to != address(0));
        vm.assume(to != self);
        vm.assume(amount > 0);
        vm.assume(supply >= amount);
        uint256 tid = 0;
        try c.createGameItem("item", "uri", true, true, supply, 0, 1) {} catch { return; }
        try c.mint(tid, amount) {} catch { return; }
        uint256 fromBefore;
        try c.balanceOf(self, tid) returns (uint256 __r) { fromBefore = __r; } catch { return; }
        uint256 toBefore;
        try c.balanceOf(to, tid) returns (uint256 __r) { toBefore = __r; } catch { return; }
        try c.safeTransferFrom(self, to, tid, amount, "") {} catch { return; }
        uint256 fromAfter;
        try c.balanceOf(self, tid) returns (uint256 __r) { fromAfter = __r; } catch { return; }
        uint256 toAfter;
        try c.balanceOf(to, tid) returns (uint256 __r) { toAfter = __r; } catch { return; }
        assertTrue(fromAfter == fromBefore - amount && toAfter == toBefore + amount);
    }

    function testFuzz_run(address to, uint256 amount, uint256 supply) public {
